export function createClayDot({getMovies,getRegion,openDetail,logo}){
 const root=document.createElement('div');root.id='claydot-root';document.body.append(root);let opened=false,step=0,answers={},mode='welcome',titleId=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const questions=[{title:'How do you want to feel?',key:'mood',options:[['bright','Light & happy','Comedy · romance · comfort'],['edge','On the edge','Crime · mystery · thriller'],['escape','Somewhere else','Fantasy · adventure · sci-fi'],['reflect','Moved & inspired','Drama · biography · stories that stay']]},{title:'What does tonight look like?',key:'format',options:[['quick','A short movie night','A film around two hours or less'],['epic','A big-screen escape','A longer, immersive film'],['series','One more episode','A TV series to settle into'],['either','Surprise me','Movies and series are both welcome']]}];
 const moods={bright:['Comedy','Romance','Family','Music'],edge:['Thriller','Crime','Mystery','Horror'],escape:['Fantasy','Adventure','Science Fiction','Animation','Supernatural'],reflect:['Drama','Biography','History','Documentary']};
 function languages(){return [...new Set(getMovies().flatMap(m=>m.languages||[]))].sort()}
 function offers(m){return m.providers.filter(p=>p.region===getRegion()||p.region==='GLOBAL')}
 function providerLinks(m){const ps=offers(m);return ps.length?ps.map(p=>`<a class="dot-offer" href="${esc(p.url)}" target="_blank" rel="noopener">${logo(p.name)}<span>${esc(p.name)}<small>${p.type==='free'||p.type==='ads'?'Free / ad-supported offer':p.type==='official-title'?'Official title page · check your region':esc(p.type)}</small></span>↗</a>`).join(''):`<p class="dot-muted">I don’t have a verified offer for ${esc(m.title)} in ${getRegion()}. I won’t guess a platform or a free stream.</p><a class="dot-offer" href="https://www.justwatch.com/${getRegion()==='IN'?'in':getRegion()==='GB'?'uk':'us'}/search?q=${encodeURIComponent(m.title)}" target="_blank" rel="noopener"><span>Check this title on JustWatch<small>Search link · availability is not confirmed</small></span>↗</a>`}
 function freeLinks(){return `<div class="dot-free"><b>Explore legal free catalogs</b><p>These are service catalogs, not confirmation that this title is free. Region restrictions and ads may apply.</p><a href="https://tubitv.com/" target="_blank" rel="noopener">${logo('Tubi')} Tubi ↗</a><a href="https://watch.plex.tv/on-demand" target="_blank" rel="noopener">${logo('Plex')} Plex ↗</a><a href="https://pluto.tv/" target="_blank" rel="noopener">${logo('Pluto TV')} Pluto TV ↗</a></div>`}
 function result(){const wanted=moods[answers.mood]||[];return getMovies().filter(m=>m.metadataStatus!=='index-only'&&(!answers.language||answers.language==='Any language'||(m.languages||[]).includes(answers.language))&&(answers.format==='either'||answers.format==='series'&&m.mediaType==='tv'||answers.format==='quick'&&m.mediaType!=='tv'&&m.runtime&&m.runtime<=125||answers.format==='epic'&&m.mediaType!=='tv'&&m.runtime&&m.runtime>125)).map(m=>({m,match:m.genres.filter(g=>wanted.includes(g))})).filter(x=>x.match.length).sort((a,b)=>(b.match.length*10+(b.m.score||0))-(a.match.length*10+(a.m.score||0))).slice(0,3)}
 function body(){if(mode==='where'){const m=getMovies().find(m=>m.id===titleId);return m?`<span class="dot-kicker">WHERE TO WATCH · ${getRegion()}</span><h3>${esc(m.title)}</h3><p>Here’s what the catalog can confirm.</p>${providerLinks(m)}${freeLinks()}<button class="dot-text" data-home>← Back to clayDot</button>`:''}
 if(mode==='questions'&&step<2){const q=questions[step];return `<span class="dot-kicker">QUESTION ${step+1} OF 3</span><div class="dot-progress"><i style="width:${(step+1)/3*100}%"></i></div><h3>${q.title}</h3><div class="dot-options">${q.options.map(([v,t,d])=>`<button data-answer="${v}"><strong>${t}</strong><small>${d}</small><span>↗</span></button>`).join('')}</div><button class="dot-text" data-home>Start again</button>`}
 if(mode==='questions'){return `<span class="dot-kicker">QUESTION 3 OF 3</span><div class="dot-progress"><i style="width:100%"></i></div><h3>Which language feels right?</h3><p>I’ll match the catalog’s original-language metadata.</p><div class="dot-language-options">${['Any language',...languages()].map(l=>`<button data-answer="${esc(l)}">${esc(l)}</button>`).join('')}</div><button class="dot-text" data-home>Start again</button>`}
 if(mode==='results'){const matches=result();return `<span class="dot-kicker">YOUR MOVIE-NIGHT EDIT</span><h3>A little mood. A good story.</h3><p>Matched to your three answers using catalog genres, format and language.</p>${matches.length?matches.map(({m,match})=>`<article class="dot-result"><button data-explore="${m.id}">${m.poster?`<img src="${esc(m.poster)}" alt="">`:''}<span><strong>${esc(m.title)}</strong><small>${m.year} · ${esc((m.languages||[]).join(' / '))} · ${m.mediaType==='tv'?'Series':'Movie'}</small><em>Because you chose ${esc(answers.mood)}: ${esc(match.join(' · '))}</em></span></button><button class="dot-watch" data-where="${m.id}">Where can I watch? ↗</button></article>`).join(''):'<p class="dot-muted">No enriched titles match all three choices yet. Try another language or format.</p>'}<button class="dot-primary" data-start>Find another mood</button>`}
 return `<span class="dot-kicker">A SMALL DOT. A GREAT NEXT WATCH.</span><h3>Your mood.<br>Your next great story.</h3><p>Hi, I’m clayDot. Answer three quick questions and I’ll put together a little watchlist for tonight.</p><button class="dot-primary" data-start>Find my next watch &nbsp; ✦</button><div class="dot-divider">or ask where to watch</div><form id="dot-search"><label><input name="title" aria-label="Ask clayDot about a title" placeholder="Movie or series name…" required autocomplete="off"></label><button aria-label="Find watch options">↗</button></form><div id="dot-search-results"></div>${freeLinks()}`}
 function draw(){root.innerHTML=`<button class="claydot-launcher" aria-label="${opened?'Close':'Open'} clayDot movie assistant" aria-expanded="${opened}"><span class="dot-orb"><i></i><i></i></span>${opened?'':'<span class="dot-label">Ask clayDot</span>'}</button>${opened?`<section class="claydot-panel" role="dialog" aria-label="clayDot movie assistant"><header><div class="dot-orb tiny"><i></i><i></i></div><div><b>clay<span>Dot</span></b><small>Your cinema companion</small></div><button data-close aria-label="Close clayDot">×</button></header><div class="claydot-body">${body()}</div><footer>Catalog matching · No generative AI model connected</footer></section>`:''}`;root.querySelector('.claydot-launcher').onclick=()=>{opened=!opened;draw()};root.querySelector('[data-close]')?.addEventListener('click',()=>{opened=false;draw()});root.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{mode='questions';step=0;answers={};draw()});root.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{mode='welcome';draw()});root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[step<2?questions[step].key:'language']=b.dataset.answer;step++;if(step===3)mode='results';draw()});root.querySelectorAll('[data-where]').forEach(b=>b.onclick=()=>where(+b.dataset.where));root.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>openDetail(+b.dataset.explore));root.querySelector('#dot-search')?.addEventListener('submit',e=>{e.preventDefault();const q=new FormData(e.target).get('title').trim().toLowerCase();const list=getMovies().filter(m=>m.title.toLowerCase().includes(q)).slice(0,6);root.querySelector('#dot-search-results').innerHTML=list.length?list.map(m=>`<button class="dot-title-result" data-where="${m.id}">${esc(m.title)} <small>${m.year}</small> ↗</button>`).join(''):'<p class="dot-muted">No matching catalog title. Try its original title.</p>';root.querySelectorAll('[data-where]').forEach(b=>b.onclick=()=>where(+b.dataset.where))})}
 function where(id){titleId=id;mode='where';opened=true;draw()}
 draw();return {where,isOpen:()=>opened};
}
